import type { SyncStatus } from "../api/sync";
import { useTranslate } from "../i18n/context";
import { CheckboxField } from "../ui/form";
import { PageSection } from "../ui/page";
import { PasswordInput } from "../ui/PasswordField";
import { Button } from "../ui/surface";
import type { SyncSetupForm } from "./useSyncSetupForm";

// The shared key that encrypts snapshots: generated by the engine or typed
// in. Replacing it reseals only the live snapshot. The history stays in the
// bucket sealed with the old key, so sshc can no longer read it while anyone
// who knows the old key still can; the confirmation says both.
export function SyncKeySection({ status, busy, form, onSave }: {
  status: SyncStatus;
  busy: boolean;
  form: Pick<SyncSetupForm, "chooseOwn" | "setChooseOwn" | "ownKey" | "setOwnKey" | "confirmHistoryLoss" | "setConfirmHistoryLoss">;
  onSave: () => void;
}) {
  const t = useTranslate();
  const { chooseOwn, setChooseOwn, ownKey, setOwnKey, confirmHistoryLoss, setConfirmHistoryLoss } = form;
  return (
    <PageSection
      heading={t("sync.key")}
      headingId="sync-key-heading"
      actions={(
        <span
          className={`rounded-full px-2.5 py-0.5 text-[11.5px] font-medium ${status.keyConfigured ? "bg-select-fill text-accent" : "bg-notice text-notice-ink"}`}
        >
          {status.keyConfigured
            ? t("sync.keyReady")
            : t("sync.keyNeeded")}
        </span>
      )}
    >
      <div className="flex flex-col gap-3">
        <p className="text-sm leading-6 text-ink-muted">
          {t("sync.keyHint")}
        </p>
        <p className="text-sm font-medium text-ink">
          {t(status.keyConfigured ? "sync.keySet" : "sync.keyMissing")}
        </p>
        <div className="flex flex-col gap-3 border-t border-line pt-3">
          <CheckboxField label={t("sync.keyChooseOwn")} checked={chooseOwn} onChange={setChooseOwn} />
          {chooseOwn ? (
            <PasswordInput
              label={t("sync.keyOwnValue")}
              value={ownKey}
              onChange={setOwnKey}
            />
          ) : null}
          {status.keyConfigured ? (
            <CheckboxField label={t("sync.keyHistoryLossConfirm")} checked={confirmHistoryLoss} onChange={setConfirmHistoryLoss} tone="danger" />
          ) : null}
          <Button
            kind="primary"
            disabled={
              busy ||
              (chooseOwn && ownKey === "") ||
              (status.keyConfigured && !confirmHistoryLoss)
            }
            onClick={onSave}
            className="self-start"
          >
            {status.keyConfigured
              ? t("sync.keyReplace")
              : t("sync.keyCreate")}
          </Button>
        </div>
      </div>
    </PageSection>
  );
}
